insert into public.questions(id,content,topic,is_public) values
('a1000000-0000-4000-8000-000000000001','{"id":"a1000000-0000-4000-8000-000000000001","title":"O trajeto até a escola","topic":"Cinemática","difficulty":"Fácil","source":"autoral","statement":"Um ônibus escolar percorre um trecho retilíneo de 1,5 km com velocidade constante de 36 km/h. Ele transporta 24 estudantes. Desconsiderando paradas, quanto tempo, em segundos, o ônibus leva para percorrer esse trecho?","diagram":["A · saída","1.500 m · v constante","B · escola"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a aceleração do ônibus","Determinar a distância por estudante","Calcular a velocidade final","Determinar o tempo de percurso"],"correct":[3],"explanation":"O objetivo é determinar o tempo de percurso.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar o tempo de percurso."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Distância: 1,5 km","Velocidade: 36 km/h","24 estudantes"],"correct":[0,1],"explanation":"Distância e velocidade são relevantes. O número de estudantes é uma distração: não interfere no tempo de um movimento com velocidade já informada.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Distância: 1,5 km e Velocidade: 36 km/h."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Velocidade constante → ônibus parado","Trecho retilíneo → velocidade aumentando","Velocidade constante → aceleração igual a zero"],"correct":[2],"explanation":"Velocidade constante → aceleração igual a zero","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Velocidade constante → aceleração igual a zero"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["1,5 km = 150 m; 36 km/h = 10 m/s","Não converter: o resultado já será em segundos","1,5 km = 1.500 m; 36 km/h = 10 m/s"],"correct":[2],"explanation":"Converta km para m multiplicando por 1.000 e km/h para m/s dividindo por 3,6.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","Converta km para m multiplicando por 1.000 e km/h para m/s dividindo por 3,6."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["Queda livre: aceleração da gravidade","MRUV: velocidade varia uniformemente","MRU: deslocamento com velocidade constante"],"correct":[2],"explanation":"No MRU, a distância percorrida é proporcional ao tempo.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","No MRU, a distância percorrida é proporcional ao tempo."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","A · saída → 1.500 m · v constante → B · escola"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["F = m · a","E = m · g · h","Δt = Δs / v","v = v₀ + a · t"],"correct":[2],"explanation":"A relação adequada é Δt = Δs / v. No MRU, a distância percorrida é proporcional ao tempo.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use Δt = Δs / v."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["Δt = 1.500 × 10","Δt = 1,5 / 36","Δt = 1.500 / 10"],"correct":[2],"explanation":"A substituição correta é Δt = 1.500 / 10.","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","Δt = 1.500 / 10"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["1.500 ÷ 10 = 15","1.500 ÷ 10 = 1.490","1.500 ÷ 10 = 150"],"correct":[2],"explanation":"Neste passo: 1.500 ÷ 10 = 150.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","1.500 ÷ 10 = 150"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["15 s","54 s","1.500 s","2,5 s","150 s"],"correct":[4],"explanation":"O ônibus leva 150 s. Dividir metros por metros por segundo produz segundos; 150 s equivalem a 2,5 minutos.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","O ônibus leva 150 s. Dividir metros por metros por segundo produz segundos; 150 s equivalem a 2,5 minutos."]}]}'::jsonb,'Cinemática',true),
('a1000000-0000-4000-8000-000000000002','{"id":"a1000000-0000-4000-8000-000000000002","title":"A bicicleta saindo do repouso","topic":"Cinemática","difficulty":"Fácil","source":"autoral","statement":"Ao sair de um semáforo, uma ciclista parte do repouso e mantém aceleração de 2 m/s² durante 5 s em linha reta. Sua bicicleta tem massa de 12 kg. Qual é a velocidade da ciclista ao final desse intervalo?","diagram":["Repouso · v₀ = 0","Acelera · 2 m/s²","Após 5 s · v = ?"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a massa total","Determinar a distância até o semáforo","Calcular a força de frenagem","Determinar a velocidade final"],"correct":[3],"explanation":"O objetivo é determinar a velocidade final.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar a velocidade final."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Parte do repouso","Aceleração: 2 m/s²","Tempo: 5 s","Bicicleta: 12 kg"],"correct":[0,1,2],"explanation":"Repouso (v₀ = 0), aceleração e tempo são relevantes. A massa da bicicleta é uma distração para o cálculo da velocidade.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Parte do repouso e Aceleração: 2 m/s² e Tempo: 5 s."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Parte do repouso → a = 0","Acelera → velocidade constante","Parte do repouso → v₀ = 0"],"correct":[2],"explanation":"Parte do repouso → v₀ = 0","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Parte do repouso → v₀ = 0"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["Sim: multiplicar o tempo por 60","Sim: dividir a aceleração por 3,6","Não: m/s² e s já são compatíveis"],"correct":[2],"explanation":"A aceleração em m/s² multiplicada pelo tempo em s fornece m/s.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","A aceleração em m/s² multiplicada pelo tempo em s fornece m/s."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["MRU: velocidade constante","Equilíbrio térmico","MRUV: aceleração constante"],"correct":[2],"explanation":"Com aceleração constante, a velocidade aumenta igualmente a cada segundo.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","Com aceleração constante, a velocidade aumenta igualmente a cada segundo."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Repouso · v₀ = 0 → Acelera · 2 m/s² → Após 5 s · v = ?"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["P = E / t","F = m · g","v = v₀ + a · t","v = Δs / Δt"],"correct":[2],"explanation":"A relação adequada é v = v₀ + a · t. Com aceleração constante, a velocidade aumenta igualmente a cada segundo.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use v = v₀ + a · t."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["v = 12 × 2","v = 5 / 2","v = 0 + 2 × 5"],"correct":[2],"explanation":"A substituição correta é v = 0 + 2 × 5.","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","v = 0 + 2 × 5"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["2 × 5 = 7","2 × 5 = 25","2 × 5 = 10"],"correct":[2],"explanation":"Neste passo: 2 × 5 = 10.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","2 × 5 = 10"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["2 m/s","5 m/s","24 m/s","25 m/s","10 m/s"],"correct":[4],"explanation":"A velocidade final é 10 m/s. A cada segundo ela ganha 2 m/s; em 5 s, ganha 10 m/s.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A velocidade final é 10 m/s. A cada segundo ela ganha 2 m/s; em 5 s, ganha 10 m/s."]}]}'::jsonb,'Cinemática',true),
('a1000000-0000-4000-8000-000000000003','{"id":"a1000000-0000-4000-8000-000000000003","title":"Uma pausa no percurso","topic":"Cinemática","difficulty":"Média","source":"autoral","statement":"Uma pessoa caminha 600 m em 5 minutos, descansa por 5 minutos e depois caminha outros 600 m em 10 minutos. Ela leva uma garrafa de 500 mL. Qual é a rapidez média em todo o percurso, incluindo a pausa, em m/s?","diagram":["600 m · 5 min","Pausa · 5 min","600 m · 10 min"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular apenas a velocidade do primeiro trecho","Determinar o volume de água consumido","Calcular a aceleração na pausa","Determinar a rapidez média incluindo a pausa"],"correct":[3],"explanation":"O objetivo é determinar a rapidez média incluindo a pausa.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar a rapidez média incluindo a pausa."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Distâncias: 600 m + 600 m","Tempos: 5 + 5 + 10 minutos","Garrafa: 500 mL"],"correct":[0,1],"explanation":"Devemos somar toda a distância e todo o tempo, inclusive a pausa. O volume da garrafa é uma distração.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Distâncias: 600 m + 600 m e Tempos: 5 + 5 + 10 minutos."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Pausa → excluir tempo do total","Rapidez média → média simples das velocidades","Todo o percurso → incluir o tempo parado"],"correct":[2],"explanation":"Todo o percurso → incluir o tempo parado","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Todo o percurso → incluir o tempo parado"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["20 minutos = 200 segundos","Não: minutos e segundos são equivalentes","20 minutos = 1.200 segundos"],"correct":[2],"explanation":"O tempo total é 20 min. Multiplique por 60: 1.200 s.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","O tempo total é 20 min. Multiplique por 60: 1.200 s."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["MRU durante todo o percurso","Aceleração constante na pausa","Rapidez média: distância total dividida pelo tempo total"],"correct":[2],"explanation":"A rapidez média usa os totais e não exige velocidade constante.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","A rapidez média usa os totais e não exige velocidade constante."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","600 m · 5 min → Pausa · 5 min → 600 m · 10 min"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["a = Δv / t","F = m · a","vₘ = distância total / tempo total","vₘ = (v₁ + v₂) / 2"],"correct":[2],"explanation":"A relação adequada é vₘ = distância total / tempo total. A rapidez média usa os totais e não exige velocidade constante.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use vₘ = distância total / tempo total."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["vₘ = 1.200 / 900","vₘ = 600 / 20","vₘ = 1.200 / 1.200"],"correct":[2],"explanation":"A substituição correta é vₘ = 1.200 / 1.200.","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","vₘ = 1.200 / 1.200"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["1.200 ÷ 1.200 = 10","1.200 ÷ 1.200 = 0,1","1.200 ÷ 1.200 = 1"],"correct":[2],"explanation":"Neste passo: 1.200 ÷ 1.200 = 1.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","1.200 ÷ 1.200 = 1"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["1,33 m/s","2 m/s","30 m/s","60 m/s","1 m/s"],"correct":[4],"explanation":"A rapidez média é 1 m/s, porque foram percorridos 1.200 m em 1.200 s, contando o descanso.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A rapidez média é 1 m/s, porque foram percorridos 1.200 m em 1.200 s, contando o descanso."]}]}'::jsonb,'Cinemática',true),
('a1000000-0000-4000-8000-000000000004','{"id":"a1000000-0000-4000-8000-000000000004","title":"Frear antes da faixa","topic":"Cinemática","difficulty":"Fácil","source":"autoral","statement":"Um automóvel a 72 km/h começa a frear com aceleração constante de −4 m/s² até parar. A via tem duas faixas. Quanto tempo dura a frenagem?","diagram":["v₀ = 72 km/h","Freia · a = −4 m/s²","Para · v = 0"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a distância entre faixas","Determinar a massa do automóvel","Calcular a velocidade inicial","Determinar o tempo até parar"],"correct":[3],"explanation":"O objetivo é determinar o tempo até parar.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar o tempo até parar."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Velocidade inicial: 72 km/h","Aceleração: −4 m/s²","Velocidade final: zero","Duas faixas"],"correct":[0,1,2],"explanation":"Velocidades inicial e final e aceleração são relevantes. A quantidade de faixas é secundária para o contexto e desnecessária para a conta.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Velocidade inicial: 72 km/h e Aceleração: −4 m/s² e Velocidade final: zero."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Frear → aceleração positiva na direção do movimento","Até parar → tempo igual a zero","Até parar → v final = 0"],"correct":[2],"explanation":"Até parar → v final = 0","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Até parar → v final = 0"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["72 km/h = 72 m/s","72 km/h = 259,2 m/s","72 km/h = 20 m/s"],"correct":[2],"explanation":"Divida 72 por 3,6 para obter 20 m/s.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","Divida 72 por 3,6 para obter 20 m/s."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["MRU com velocidade constante","Movimento sem aceleração","MRUV com velocidade diminuindo"],"correct":[2],"explanation":"A aceleração tem sentido contrário à velocidade e reduz seu módulo.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","A aceleração tem sentido contrário à velocidade e reduz seu módulo."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","v₀ = 72 km/h → Freia · a = −4 m/s² → Para · v = 0"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["E = m · g · h","P = U · i","t = (v − v₀) / a","t = Δs / v"],"correct":[2],"explanation":"A relação adequada é t = (v − v₀) / a. A aceleração tem sentido contrário à velocidade e reduz seu módulo.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use t = (v − v₀) / a."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["t = 72 / 4","t = (20 − 0) / (−4)","t = (0 − 20) / (−4)"],"correct":[2],"explanation":"A substituição correta é t = (0 − 20) / (−4).","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","t = (0 − 20) / (−4)"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["(−20) ÷ (−4) = −5","(−20) ÷ (−4) = 80","(−20) ÷ (−4) = 5"],"correct":[2],"explanation":"Neste passo: (−20) ÷ (−4) = 5.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","(−20) ÷ (−4) = 5"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["18 s","−5 s","20 s","80 s","5 s"],"correct":[4],"explanation":"A frenagem dura 5 s. A velocidade diminui 4 m/s a cada segundo, partindo de 20 m/s.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A frenagem dura 5 s. A velocidade diminui 4 m/s a cada segundo, partindo de 20 m/s."]}]}'::jsonb,'Cinemática',true),
('a1000000-0000-4000-8000-000000000005','{"id":"a1000000-0000-4000-8000-000000000005","title":"A queda de uma pequena esfera","topic":"Cinemática","difficulty":"Fácil","source":"autoral","statement":"Uma pequena esfera é abandonada do repouso de uma altura de 20 m. Despreze a resistência do ar e adote g = 10 m/s². A esfera é azul. Quanto tempo leva para atingir o chão?","diagram":["Altura · 20 m","Queda · g = 10 m/s²","Chão · t = ?"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a cor da esfera","Determinar a massa da esfera","Calcular a aceleração da gravidade","Determinar o tempo de queda"],"correct":[3],"explanation":"O objetivo é determinar o tempo de queda.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar o tempo de queda."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Altura: 20 m","Abandonada do repouso","g = 10 m/s²","Cor azul"],"correct":[0,1,2],"explanation":"Altura, velocidade inicial nula e gravidade entram na conta. A cor é uma distração; desprezar o ar é uma condição relevante do modelo.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Altura: 20 m e Abandonada do repouso e g = 10 m/s²."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Abandonada → gravidade nula","Sem resistência do ar → sem aceleração","Abandonada → velocidade inicial nula"],"correct":[2],"explanation":"Abandonada → velocidade inicial nula","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Abandonada → velocidade inicial nula"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["Sim: converter 20 m para km","Sim: dividir g por 3,6","Não: metros e segundos são compatíveis"],"correct":[2],"explanation":"Altura em metros e gravidade em m/s² produzem tempo em segundos.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","Altura em metros e gravidade em m/s² produzem tempo em segundos."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["MRU vertical","Equilíbrio estático","Queda livre com aceleração constante"],"correct":[2],"explanation":"Na queda livre a partir do repouso, h = g · t² / 2.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","Na queda livre a partir do repouso, h = g · t² / 2."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Altura · 20 m → Queda · g = 10 m/s² → Chão · t = ?"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["t = g / h","v = h · t","t = √(2h / g)","t = h / g"],"correct":[2],"explanation":"A relação adequada é t = √(2h / g). Na queda livre a partir do repouso, h = g · t² / 2.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use t = √(2h / g)."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["t = 20 / 10","t = √(20 × 10)","t = √(2 × 20 / 10)"],"correct":[2],"explanation":"A substituição correta é t = √(2 × 20 / 10).","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","t = √(2 × 20 / 10)"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["√4 = 4","√4 = 16","√4 = 2"],"correct":[2],"explanation":"Neste passo: √4 = 2.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","√4 = 2"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["4 s","1 s","20 s","0,5 s","2 s"],"correct":[4],"explanation":"O tempo de queda é 2 s. A raiz é necessária porque a equação contém t²; consideramos a raiz positiva para o tempo.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","O tempo de queda é 2 s. A raiz é necessária porque a equação contém t²; consideramos a raiz positiva para o tempo."]}]}'::jsonb,'Cinemática',true),
('a1000000-0000-4000-8000-000000000006','{"id":"a1000000-0000-4000-8000-000000000006","title":"O carrinho do mercado","topic":"Dinâmica","difficulty":"Média","source":"autoral","statement":"Um carrinho com compras tem massa total de 20 kg. Uma pessoa o empurra horizontalmente com força de 50 N. O atrito exerce 10 N no sentido contrário. Há 8 produtos no carrinho. Qual é o módulo da aceleração horizontal?","diagram":["Atrito · 10 N ←","Carrinho · 20 kg","→ Empurrão · 50 N"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular o peso de cada produto","Determinar a velocidade final","Calcular o trabalho total","Determinar a aceleração horizontal"],"correct":[3],"explanation":"O objetivo é determinar a aceleração horizontal.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar a aceleração horizontal."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Massa total: 20 kg","Força aplicada: 50 N","Atrito contrário: 10 N","8 produtos"],"correct":[0,1,2],"explanation":"Massa total e forças horizontais são relevantes. A quantidade de produtos não é necessária porque a massa total já foi dada.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Massa total: 20 kg e Força aplicada: 50 N e Atrito contrário: 10 N."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Atrito contrário → somar as intensidades","Empurrar → velocidade sempre constante","Atrito contrário → subtrair da força aplicada"],"correct":[2],"explanation":"Atrito contrário → subtrair da força aplicada","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Atrito contrário → subtrair da força aplicada"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["Sim: transformar kg em g","Sim: converter N para km/h","Não: kg e N já estão no SI"],"correct":[2],"explanation":"Newton corresponde a kg·m/s². Ao dividir força por massa, obtemos m/s².","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","Newton corresponde a kg·m/s². Ao dividir força por massa, obtemos m/s²."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["Equilíbrio: força resultante igual a zero","Conservação da temperatura","Segunda lei de Newton: força resultante causa aceleração"],"correct":[2],"explanation":"Use a força resultante, e não somente a força aplicada, em Fᵣ = m · a.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","Use a força resultante, e não somente a força aplicada, em Fᵣ = m · a."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Atrito · 10 N ← → Carrinho · 20 kg → → Empurrão · 50 N"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["a = (F + f) / m","v = Δs / t","a = (F − f) / m","a = F · m"],"correct":[2],"explanation":"A relação adequada é a = (F − f) / m. Use a força resultante, e não somente a força aplicada, em Fᵣ = m · a.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use a = (F − f) / m."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["a = 50 / 20","a = (50 + 10) / 20","a = (50 − 10) / 20"],"correct":[2],"explanation":"A substituição correta é a = (50 − 10) / 20.","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","a = (50 − 10) / 20"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["60 ÷ 20 = 3","50 ÷ 20 = 2,5","40 ÷ 20 = 2"],"correct":[2],"explanation":"Neste passo: 40 ÷ 20 = 2.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","40 ÷ 20 = 2"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["3 m/s²","2,5 m/s²","40 m/s²","0,5 m/s²","2 m/s²"],"correct":[4],"explanation":"A força resultante é 40 N. Dividindo por 20 kg, a aceleração é 2 m/s², no sentido do empurrão.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A força resultante é 40 N. Dividindo por 20 kg, a aceleração é 2 m/s², no sentido do empurrão."]}]}'::jsonb,'Dinâmica',true),
('a1000000-0000-4000-8000-000000000007','{"id":"a1000000-0000-4000-8000-000000000007","title":"Uma mochila na prateleira","topic":"Trabalho e Energia","difficulty":"Fácil","source":"autoral","statement":"Uma estudante levanta lentamente uma mochila de 4 kg do chão até uma prateleira a 1,5 m de altura. O movimento dura 3 s. Adote g = 10 m/s². Qual é o aumento da energia potencial gravitacional da mochila?","diagram":["Chão · h = 0","Elevação · 1,5 m","Prateleira · ΔEₚ = ?"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a potência média","Determinar a velocidade final","Calcular o peso da prateleira","Determinar o aumento da energia potencial"],"correct":[3],"explanation":"O objetivo é determinar o aumento da energia potencial.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar o aumento da energia potencial."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Massa: 4 kg","Elevação: 1,5 m","g = 10 m/s²","Duração: 3 s"],"correct":[0,1,2],"explanation":"Massa, gravidade e elevação são relevantes. O tempo seria usado para potência, mas é uma distração para a variação da energia potencial.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Massa: 4 kg e Elevação: 1,5 m e g = 10 m/s²."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Levantar lentamente → energia potencial constante","Dura 3 s → altura igual a 3 m","Do chão à prateleira → Δh = 1,5 m"],"correct":[2],"explanation":"Do chão à prateleira → Δh = 1,5 m","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Do chão à prateleira → Δh = 1,5 m"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["Sim: usar 150 m para a altura","Sim: converter segundos para horas","Não: kg, m e m/s² já estão compatíveis"],"correct":[2],"explanation":"O produto kg·m/s²·m resulta em joules (J).","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","O produto kg·m/s²·m resulta em joules (J)."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["Diminuição da energia potencial","Aquecimento por efeito Joule","Aumento da energia potencial gravitacional"],"correct":[2],"explanation":"A energia potencial gravitacional aumenta com a altura: ΔEₚ = m · g · Δh.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","A energia potencial gravitacional aumenta com a altura: ΔEₚ = m · g · Δh."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Chão · h = 0 → Elevação · 1,5 m → Prateleira · ΔEₚ = ?"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["E꜀ = m · v² / 2","F = m · a","ΔEₚ = m · g · Δh","P = E / t"],"correct":[2],"explanation":"A relação adequada é ΔEₚ = m · g · Δh. A energia potencial gravitacional aumenta com a altura: ΔEₚ = m · g · Δh.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use ΔEₚ = m · g · Δh."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["ΔEₚ = 4 × 10 × 3","ΔEₚ = 4 × 1,5 / 3","ΔEₚ = 4 × 10 × 1,5"],"correct":[2],"explanation":"A substituição correta é ΔEₚ = 4 × 10 × 1,5.","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","ΔEₚ = 4 × 10 × 1,5"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["40 × 1,5 = 6","40 × 1,5 = 600","40 × 1,5 = 60"],"correct":[2],"explanation":"Neste passo: 40 × 1,5 = 60.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","40 × 1,5 = 60"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["20 J","120 J","6 J","40 J","60 J"],"correct":[4],"explanation":"A energia potencial aumenta 60 J. O tempo de 3 s não entra nesse cálculo.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A energia potencial aumenta 60 J. O tempo de 3 s não entra nesse cálculo."]}]}'::jsonb,'Trabalho e Energia',true),
('a1000000-0000-4000-8000-000000000008','{"id":"a1000000-0000-4000-8000-000000000008","title":"Uma lâmpada no circuito","topic":"Eletricidade","difficulty":"Fácil","source":"autoral","statement":"Uma lâmpada recebe tensão de 12 V e é percorrida por corrente de 0,5 A durante seu funcionamento. Ela permanece ligada por 2 horas. Qual é a potência elétrica consumida pela lâmpada nessas condições?","diagram":["Fonte · 12 V","Corrente · 0,5 A","Lâmpada · P = ?"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a energia em duas horas","Determinar o tempo de funcionamento","Calcular a carga total","Determinar a potência elétrica"],"correct":[3],"explanation":"O objetivo é determinar a potência elétrica.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar a potência elétrica."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Tensão: 12 V","Corrente: 0,5 A","Tempo: 2 h"],"correct":[0,1],"explanation":"Tensão e corrente são relevantes para potência. O tempo é secundário: só seria necessário para calcular a energia consumida.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Tensão: 12 V e Corrente: 0,5 A."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Potência → energia total em duas horas","Corrente → tensão por segundo","Potência → energia transformada por unidade de tempo"],"correct":[2],"explanation":"Potência → energia transformada por unidade de tempo","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Potência → energia transformada por unidade de tempo"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["Sim: converter duas horas para segundos","Sim: trocar 0,5 A por 500 A","Não: V × A resulta em W"],"correct":[2],"explanation":"Tensão em volts e corrente em amperes fornecem potência em watts.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","Tensão em volts e corrente em amperes fornecem potência em watts."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["Geração de energia do nada","Equilíbrio gravitacional","Transformação de energia elétrica em luz e calor"],"correct":[2],"explanation":"A potência elétrica de um componente é o produto da tensão pela corrente.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","A potência elétrica de um componente é o produto da tensão pela corrente."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Fonte · 12 V → Corrente · 0,5 A → Lâmpada · P = ?"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["R = U / i","Q = m · c · ΔT","P = U · i","E = P · t"],"correct":[2],"explanation":"A relação adequada é P = U · i. A potência elétrica de um componente é o produto da tensão pela corrente.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use P = U · i."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["P = 12 × 0,5 × 2","P = 12 / 0,5","P = 12 × 0,5"],"correct":[2],"explanation":"A substituição correta é P = 12 × 0,5.","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","P = 12 × 0,5"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["12 × 0,5 = 24","12 × 0,5 = 60","12 × 0,5 = 6"],"correct":[2],"explanation":"Neste passo: 12 × 0,5 = 6.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","12 × 0,5 = 6"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["12 W","24 W","0,5 W","60 W","6 W"],"correct":[4],"explanation":"A potência é 6 W. Multiplicar pelo tempo daria energia, outra grandeza.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A potência é 6 W. Multiplicar pelo tempo daria energia, outra grandeza."]}]}'::jsonb,'Eletricidade',true),
('a1000000-0000-4000-8000-000000000009','{"id":"a1000000-0000-4000-8000-000000000009","title":"O consumo do chuveiro","topic":"Eletricidade","difficulty":"Média","source":"autoral","statement":"Um chuveiro elétrico de potência nominal de 5.500 W é usado durante 20 minutos, operando nessa potência. A água entra a 22 °C. Qual energia elétrica é consumida nesse banho, aproximadamente, em kWh?","diagram":["Potência · 5,5 kW","Uso · 1/3 h","Energia · ? kWh"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a temperatura final da água","Determinar a corrente elétrica","Calcular a resistência do chuveiro","Determinar a energia consumida em kWh"],"correct":[3],"explanation":"O objetivo é determinar a energia consumida em kwh.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar a energia consumida em kwh."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Potência: 5.500 W","Tempo: 20 min","Temperatura inicial: 22 °C"],"correct":[0,1],"explanation":"Potência e tempo determinam a energia consumida. A temperatura inicial é secundária neste cálculo, pois a potência já foi informada.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Potência: 5.500 W e Tempo: 20 min."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["5.500 W → 5.500 kWh consumidos","20 minutos → 0,20 hora","Opera nessa potência → P constante durante o banho"],"correct":[2],"explanation":"Opera nessa potência → P constante durante o banho","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","Opera nessa potência → P constante durante o banho"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["5.500 W = 55 kW; 20 min = 0,2 h","Não: W e minutos produzem kWh","5.500 W = 5,5 kW; 20 min = 1/3 h"],"correct":[2],"explanation":"Divida W por 1.000 e minutos por 60 para obter kW e h.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","Divida W por 1.000 e minutos por 60 para obter kW e h."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["Conservação da velocidade","Equilíbrio de forças","Consumo de energia elétrica com potência constante"],"correct":[2],"explanation":"A energia consumida é potência multiplicada pelo tempo de uso.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","A energia consumida é potência multiplicada pelo tempo de uso."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Potência · 5,5 kW → Uso · 1/3 h → Energia · ? kWh"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["R = U / i","Q = m · c · ΔT","E = P · t","P = E · t"],"correct":[2],"explanation":"A relação adequada é E = P · t. A energia consumida é potência multiplicada pelo tempo de uso.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use E = P · t."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["E = 5,5 × 0,20","E = 5.500 × 20","E = 5,5 × (1/3)"],"correct":[2],"explanation":"A substituição correta é E = 5,5 × (1/3).","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","E = 5,5 × (1/3)"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["5,5 ÷ 3 ≈ 18,3","5,5 ÷ 3 ≈ 0,183","5,5 ÷ 3 ≈ 1,83"],"correct":[2],"explanation":"Neste passo: 5,5 ÷ 3 ≈ 1,83.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","5,5 ÷ 3 ≈ 1,83"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["1,10 kWh","18,3 kWh","110 kWh","0,55 kWh","1,83 kWh"],"correct":[4],"explanation":"O consumo é aproximadamente 1,83 kWh. Atenção: 20 minutos equivalem a 1/3 de hora, não a 0,20 h.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","O consumo é aproximadamente 1,83 kWh. Atenção: 20 minutos equivalem a 1/3 de hora, não a 0,20 h."]}]}'::jsonb,'Eletricidade',true),
('a1000000-0000-4000-8000-000000000010','{"id":"a1000000-0000-4000-8000-000000000010","title":"A água para o café","topic":"Termologia","difficulty":"Fácil","source":"autoral","statement":"Uma pessoa aquece 200 g de água de 20 °C até 70 °C, sem mudança de estado físico. Considere o calor específico da água igual a 4 J/(g·°C) e despreze perdas de calor. O recipiente é vermelho. Quanto calor a água recebe?","diagram":["Água · 20 °C","Recebe calor · Q","Água · 70 °C"],"steps":[{"title":"O que a questão quer?","prompt":"Antes de procurar números, identifique o objetivo.","category":"interpretação do comando","kind":"single","options":["Calcular a temperatura inicial","Determinar o calor para vaporizar a água","Calcular a massa do recipiente","Determinar o calor recebido pela água"],"correct":[3],"explanation":"O objetivo é determinar o calor recebido pela água.","hints":["Releia a última frase do enunciado.","Separe o que já foi informado daquilo que precisa ser descoberto.","Procure a alternativa que pede determinar o calor recebido pela água."]},{"title":"Quais dados importam?","prompt":"Selecione todos os dados necessários para resolver. Pode haver mais de um.","category":"identificação de dados","kind":"multiple","options":["Massa: 200 g","Temperaturas: 20 °C e 70 °C","Calor específico: 4 J/(g·°C)","Recipiente vermelho"],"correct":[0,1,2],"explanation":"Massa, variação de temperatura e calor específico são relevantes. A cor do recipiente é uma distração; a ausência de mudança de estado define o modelo de calor sensível.","hints":["Compare cada informação com o objetivo da questão.","O contexto pode trazer números que não entram na conta.","Você precisa de Massa: 200 g e Temperaturas: 20 °C e 70 °C e Calor específico: 4 J/(g·°C)."]},{"title":"Traduzindo o enunciado","prompt":"Qual tradução representa melhor a situação?","category":"interpretação do fenômeno","kind":"single","options":["Temperatura final → ΔT = 70 °C","Sem mudança de estado → não recebe calor","De 20 °C a 70 °C → ΔT = 50 °C"],"correct":[2],"explanation":"De 20 °C a 70 °C → ΔT = 50 °C","hints":["Repare nas palavras que descrevem o comportamento físico.","Uma expressão cotidiana pode representar uma condição física.","De 20 °C a 70 °C → ΔT = 50 °C"]},{"title":"Preciso converter unidades?","prompt":"Escolha como preparar as unidades antes da conta.","category":"conversão de unidade","kind":"single","options":["Sim: mudar só a massa para kg","Sim: usar 343 como variação de temperatura","Não: massa em g combina com c em J/(g·°C)"],"correct":[2],"explanation":"As unidades já são compatíveis. Não converta apenas a massa para kg mantendo c por grama.","hints":["Veja em qual unidade a resposta foi pedida.","Confira se tempo, distância e demais grandezas usam unidades compatíveis.","As unidades já são compatíveis. Não converta apenas a massa para kg mantendo c por grama."]},{"title":"Qual fenômeno e conceito?","prompt":"O que explica fisicamente esta situação?","category":"interpretação do fenômeno","kind":"single","options":["Calor latente: mudança de fase","MRUV","Calor sensível: temperatura varia sem mudança de fase"],"correct":[2],"explanation":"O calor sensível depende de massa, calor específico e variação de temperatura.","hints":["Descreva mentalmente o que muda e o que permanece constante.","Relacione esse comportamento com uma lei física.","O calor sensível depende de massa, calor específico e variação de temperatura."]},{"title":"Vamos visualizar","prompt":"Observe o esquema. Ele representa as informações do enunciado, sem escala.","category":"interpretação do fenômeno","kind":"visual","options":["Observei o esquema","Vou reler o enunciado"],"correct":[0],"hints":["Leia o esquema da esquerda para a direita.","Associe cada rótulo a uma informação da questão.","Água · 20 °C → Recebe calor · Q → Água · 70 °C"],"explanation":"O esquema ajuda a organizar a situação antes de escolher uma equação."},{"title":"Qual fórmula faz sentido?","prompt":"Escolha a relação que conecta os dados ao que foi pedido.","category":"escolha de fórmula","kind":"single","options":["P = U · i","E = m · g · h","Q = m · c · ΔT","Q = m · L"],"correct":[2],"explanation":"A relação adequada é Q = m · c · ΔT. O calor sensível depende de massa, calor específico e variação de temperatura.","hints":["Procure a grandeza desconhecida nas fórmulas.","A fórmula deve conter os dados que você tem.","Use Q = m · c · ΔT."]},{"title":"Cálculo: substituindo os dados","prompt":"Como ficam os valores na relação escolhida?","category":"cálculo","kind":"single","options":["Q = 200 × 4 × 70","Q = 0,2 × 4 × 50","Q = 200 × 4 × (70 − 20)"],"correct":[2],"explanation":"A substituição correta é Q = 200 × 4 × (70 − 20).","hints":["Use apenas os dados selecionados, nas unidades corretas.","Substitua cada símbolo por seu valor, sem trocar a ordem.","Q = 200 × 4 × (70 − 20)"]},{"title":"Cálculo: um passo por vez","prompt":"Efetue a operação. Qual resultado intermediário faz sentido?","category":"cálculo","kind":"single","options":["800 × 50 = 4.000","800 × 50 = 400","800 × 50 = 40.000"],"correct":[2],"explanation":"Neste passo: 800 × 50 = 40.000.","hints":["Respeite parênteses e a ordem das operações.","Verifique divisões e multiplicações antes de somar.","800 × 50 = 40.000"]},{"title":"Agora, qual é a resposta?","prompt":"Escolha a alternativa e confira se ela responde ao que foi pedido.","category":"cálculo","kind":"single","options":["56.000 J","4.000 J","40 J","800 J","40.000 J"],"correct":[4],"explanation":"A água recebe 40.000 J (40 kJ). Usamos a variação de 50 °C, não a temperatura final de 70 °C.","hints":["Volte ao objetivo que identificamos no primeiro passo.","Confira o valor, a unidade e se o resultado é plausível.","A água recebe 40.000 J (40 kJ). Usamos a variação de 50 °C, não a temperatura final de 70 °C."]}]}'::jsonb,'Termologia',true)
